package com.aistock.gateway.adminmarket;
import com.aistock.common.*;import com.aistock.common.adminrefresh.*;import com.aistock.common.adminrefresh.AdminMarketRefreshRecords.*;import com.aistock.gateway.*;import com.aistock.gateway.security.AdminReadAccess;import com.fasterxml.jackson.databind.*;import jakarta.servlet.http.*;import java.io.IOException;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.util.MultiValueMap;import org.springframework.web.bind.annotation.*;
@RestController public class AdminMarketRefreshProxyController {
 private final SchedulerPublicClient client;private final AdminReadAccess access;private final ObjectMapper mapper;private final Set<String> origins;
 private static final Set<String> CONFLICT=Set.of("REFRESH_ACTIONS_DISABLED","REFRESH_WORKER_DISABLED","REFRESH_CONTEXT_CHANGED","REFRESH_RANGE_UNSUPPORTED","REFRESH_COOLDOWN","ACTIVE_REFRESH_EXISTS","OPERATION_KEY_CONFLICT");
 public AdminMarketRefreshProxyController(SchedulerPublicClient client,AdminReadAccess access,ObjectMapper mapper,@Value("${aistock.auth.allowed-origins:http://127.0.0.1:15173,http://localhost:15173}")String origins){this.client=client;this.access=access;this.mapper=mapper.copy().disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);this.origins=Set.copyOf(Arrays.stream(origins.split(",")).map(String::strip).toList());}
 @RequestMapping({"/api/v1/admin/market-data/{instrumentId}/refresh-options","/api/v1/admin/market-data/{instrumentId}/refresh-operations","/api/v1/admin/market-data/refresh-operations/{operationId}"})
 public ResponseEntity<byte[]> handle(HttpServletRequest r,HttpServletResponse response,@RequestParam MultiValueMap<String,String> query)throws IOException{
  response.setHeader("Cache-Control","no-store");String path=r.getRequestURI();boolean post="POST".equals(r.getMethod());
  if(!(post?AdminMarketRefreshInput.writePath(path):"GET".equals(r.getMethod())&&AdminMarketRefreshInput.readPath(path)))throw new BusinessException("RESOURCE_NOT_FOUND","接口不存在",HttpStatus.NOT_FOUND);
  access.requireAdmin(r);byte[] body=null;Command command=null;
  if(post){if(!origins.contains(Objects.toString(single(r,"Origin"),""))||!"1".equals(single(r,"X-Aistock-Admin-Action")))throw new BusinessException("TASK_ACTION_ORIGIN_DENIED","当前来源不允许提交操作",HttpStatus.FORBIDDEN);try{var type=MediaType.parseMediaType(Objects.requireNonNull(single(r,"Content-Type")));if(!"application".equals(type.getType())||!"json".equals(type.getSubtype()))throw AdminMarketRefreshInput.invalid();}catch(RuntimeException e){throw AdminMarketRefreshInput.invalid();}if(!query.isEmpty()||r.getContentLengthLong()>4096)throw AdminMarketRefreshInput.invalid();body=r.getInputStream().readNBytes(4097);command=AdminMarketRefreshInput.parse(body);}
  else{if(r.getInputStream().read()!=-1)throw AdminMarketRefreshInput.invalid();if(path.endsWith("/refresh-operations"))AdminMarketRefreshInput.history(query);else if(!query.isEmpty())throw AdminMarketRefreshInput.invalid();}
  try{ResponseEntity<byte[]> reply;try{reply=post?client.post(path.substring(8),body,ProxyHeaderPolicy.request(r)):client.get(path.substring(8),query,ProxyHeaderPolicy.request(r));}catch(feign.FeignException e){reply=ResponseEntity.status(e.status()>0?e.status():503).body(e.content());}return validate(r,reply,command);}
  catch(BusinessException e){throw e;}catch(RuntimeException|IOException e){throw unavailable();}
 }
 private ResponseEntity<byte[]> validate(HttpServletRequest r,ResponseEntity<byte[]> reply,Command command)throws IOException{
  if(reply==null||reply.getBody()==null||reply.getBody().length>262144)throw unavailable();var n=mapper.reader().with(DeserializationFeature.FAIL_ON_TRAILING_TOKENS).readTree(reply.getBody());if(n==null||!n.isObject())throw unavailable();int status=reply.getStatusCode().value();String code=n.path("code").asText();var data=n.path("data");Object safe;
  if(status==200&&"OK".equals(code)){if(!data.isObject())throw unavailable();if(command!=null)safe=checkedReceipt(data,command,r,200,code);else safe=checkedRead(r,data);}
  else if(status==409&&CONFLICT.contains(code)&&data.isObject()&&command!=null)safe=checkedReceipt(data,command,r,409,code);
  else{boolean known=(status==400&&"ADMIN_REFRESH_REQUEST_INVALID".equals(code))||(status==401&&"AUTH_REQUIRED".equals(code))||(status==403&&Set.of("ACCESS_DENIED","TASK_ACTION_ORIGIN_DENIED").contains(code))||(status==404&&Set.of("OPERATION_NOT_FOUND","MARKET_ADMIN_RESOURCE_NOT_FOUND").contains(code))||(status==409&&CONFLICT.contains(code))||(status==503&&Set.of("USER_SERVICE_UNAVAILABLE","MARKET_ADMIN_UNAVAILABLE","REFRESH_ACTION_UNAVAILABLE").contains(code));if(!known||!data.isNull())throw unavailable();safe=null;}
  return ResponseEntity.status(status).contentType(MediaType.APPLICATION_JSON).cacheControl(CacheControl.noStore()).body(mapper.writeValueAsBytes(new ApiResponse<>(code,status==200?"成功":"操作未完成，请核对条件或查询原记录",safe,TraceIds.normalize(r.getHeader("X-Trace-Id")))));
 }
 private Object checkedRead(HttpServletRequest r,JsonNode data){
  try{String path=r.getRequestURI(),stock=path.split("/")[5];
   if(path.endsWith("/refresh-options")){if(!data.path("actionsEnabled").isBoolean()||!data.path("allowed").isBoolean())throw unavailable();var v=mapper.convertValue(data,Options.class);if(v.queriedAt()==null||!stock.equals(v.instrumentId())||!AdminMarketRefreshPolicy.VERSION.equals(v.policyVersion()))throw unavailable();if(v.allowed()&&(!v.actionsEnabled()||!"baostock".equals(v.provider())||!"RAW".equals(v.priceBasis())||v.minTargetDate()==null||v.maxTargetDate()==null||v.defaultTargetDate()==null))throw unavailable();return v;}
   if(stock.equals("refresh-operations")){var v=mapper.convertValue(data,OperationView.class);checkView(v);if(!path.endsWith("/"+v.receipt().operationId()))throw unavailable();return v;}
   if(!data.path("items").isArray()||!data.path("hasMore").isBoolean())throw unavailable();var v=mapper.convertValue(data,HistoryPage.class);if(v.queriedAt()==null||!stock.equals(v.instrumentId())||v.items()==null||v.items().size()>50||v.hasMore()&&(v.nextCursor()==null||!v.nextCursor().matches("[A-Za-z0-9_-]{1,768}"))||!v.hasMore()&&v.nextCursor()!=null)throw unavailable();for(var item:v.items()){checkView(item);if(!stock.equals(item.receipt().instrumentId()))throw unavailable();}return v;
  }catch(RuntimeException e){throw unavailable();}
 }
 private void checkView(OperationView v){if(v==null||v.queriedAt()==null||v.receipt()==null)throw unavailable();var receipt=v.receipt();AdminMarketRefreshInput.id(receipt.operationId());AdminMarketRefreshInput.instrument(receipt.instrumentId());AdminMarketRefreshInput.id(receipt.actorUserId());AdminMarketRefreshInput.id(receipt.baseVersionId());AdminMarketRefreshInput.revision(receipt.headRevision());if(!Set.of("QUEUED","ATTACHED","REJECTED").contains(receipt.outcome())||receipt.targetDate()==null||receipt.requestedAt()==null||receipt.finishedAt()==null)throw unavailable();if(v.task()!=null){AdminMarketRefreshInput.id(v.task().taskId());AdminMarketRefreshInput.revision(v.task().revision());if(!Objects.equals(receipt.taskId(),v.task().taskId())||v.task().updatedAt()==null||v.task().state()==null||v.task().attemptCount()<0)throw unavailable();}else if(!"REJECTED".equals(receipt.outcome()))throw unavailable();}
 private Receipt checkedReceipt(JsonNode node,Command command,HttpServletRequest r,int status,String code){try{var v=mapper.convertValue(node,Receipt.class);if(v==null||!command.operationId().toString().equals(v.operationId())||!r.getRequestURI().split("/")[5].equals(v.instrumentId())||!command.baseVersionId().toString().equals(v.baseVersionId())||!command.expectedHeadRevision().equals(v.headRevision())||!command.targetDate().equals(v.targetDate())||!command.reasonCode().equals(v.reasonCode())||v.requestedAt()==null||v.finishedAt()==null)throw unavailable();AdminMarketRefreshInput.id(v.actorUserId());if(status==409){if(!"REJECTED".equals(v.outcome())||!code.equals(v.resultCode()))throw unavailable();}else if(!Set.of("QUEUED","ATTACHED").contains(v.outcome())||!Objects.equals(v.resultCode(),"QUEUED".equals(v.outcome())?"REFRESH_TASK_QUEUED":"REFRESH_TASK_ATTACHED"))throw unavailable();if(status==200)AdminMarketRefreshInput.id(v.taskId());return v;}catch(RuntimeException e){throw unavailable();}}
 private String single(HttpServletRequest r,String name){var values=Collections.list(r.getHeaders(name));return values.size()==1?values.get(0):null;}
 private BusinessException unavailable(){return new BusinessException("REFRESH_ACTION_UNAVAILABLE","结果暂无法确认，请查询原操作编号",HttpStatus.SERVICE_UNAVAILABLE);}
}
